CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, username text NOT NULL UNIQUE, display_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_profile ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid() OR public.has_role(auth.uid(), 'admin'));
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, username, display_name) VALUES (NEW.id, coalesce(NEW.raw_user_meta_data->>'username', split_part(NEW.email, '@', 1)), coalesce(NEW.raw_user_meta_data->>'display_name', '')); RETURN NEW; END $$;
CREATE TRIGGER create_user_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.subscriptions (user_id uuid PRIMARY KEY, expires_at timestamptz, blocked boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.subscriptions TO authenticated;
GRANT ALL ON public.subscriptions TO service_role;
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_subscription ON public.subscriptions FOR SELECT TO authenticated USING(user_id = auth.uid() OR public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, amount_cents integer NOT NULL DEFAULT 5000 CHECK(amount_cents = 5000), confirmed_by uuid NOT NULL, confirmed_at timestamptz NOT NULL DEFAULT now(), reference text NOT NULL DEFAULT '', expires_at timestamptz NOT NULL);
GRANT SELECT ON public.payments TO authenticated;
GRANT ALL ON public.payments TO service_role;
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_payments ON public.payments FOR SELECT TO authenticated USING(user_id = auth.uid() OR public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.payment_settings (id integer PRIMARY KEY DEFAULT 1 CHECK(id = 1), pix_key text NOT NULL DEFAULT '', recipient text NOT NULL DEFAULT '', contact text NOT NULL DEFAULT '');
GRANT SELECT ON public.payment_settings TO anon, authenticated;
GRANT ALL ON public.payment_settings TO service_role;
ALTER TABLE public.payment_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_payment_settings ON public.payment_settings FOR SELECT TO anon, authenticated USING(true);
CREATE FUNCTION public.confirm_monthly_payment(target uuid, actor uuid, payment_reference text) RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE new_expiry timestamptz; BEGIN IF NOT public.has_role(actor, 'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id = target) THEN RAISE EXCEPTION 'Unknown user'; END IF; INSERT INTO public.subscriptions(user_id) VALUES(target) ON CONFLICT DO NOTHING; SELECT greatest(coalesce(expires_at, now()), now()) + interval '1 month' INTO new_expiry FROM public.subscriptions WHERE user_id = target FOR UPDATE; UPDATE public.subscriptions SET expires_at = new_expiry, blocked = false WHERE user_id = target; INSERT INTO public.payments(user_id, confirmed_by, reference, expires_at) VALUES(target, actor, payment_reference, new_expiry); RETURN new_expiry; END $$;
REVOKE ALL ON FUNCTION public.confirm_monthly_payment(uuid, uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.confirm_monthly_payment(uuid, uuid, text) TO service_role;